101	abstract class MarkerModel<Opts extends MarkerOption = MarkerOption> extends ComponentModel<Opts> {
102	
103	    static type = 'marker';
104	    type = MarkerModel.type;
105	
106	    /**
107	     * If marker model is created by self from series
108	     */
109	    createdBySelf = false;
110	
111	    static readonly dependencies = ['series', 'grid', 'polar', 'geo'];
112	
113	    __hostSeries: SeriesModel;
114	
115	    private _data: SeriesData;
116	
117	    /**
118	     * @overrite
119	     */
120	    init(option: Opts, parentModel: Model, ecModel: GlobalModel) {
121	
122	        if (__DEV__) {
123	            if (this.type === 'marker') {
124	                throw new Error('Marker component is abstract component. Use markLine, markPoint, markArea instead.');
125	            }
126	        }
127	        this.mergeDefaultAndTheme(option, ecModel);
128	        this._mergeOption(option, ecModel, false, true);
129	    }
130	
131	    isAnimationEnabled(): boolean {
132	        if (env.node) {
133	            return false;
134	        }
135	
136	        const hostSeries = this.__hostSeries;
137	        return this.getShallow('animation') && hostSeries && hostSeries.isAnimationEnabled();
138	    }
139	
140	    /**
141	     * @overrite
142	     */
143	    mergeOption(newOpt: Opts, ecModel: GlobalModel) {
144	        this._mergeOption(newOpt, ecModel, false, false);
145	    }
146	
147	    _mergeOption(newOpt: Opts, ecModel: GlobalModel, createdBySelf?: boolean, isInit?: boolean) {
148	        const componentType = this.mainType;
149	        if (!createdBySelf) {
150	            ecModel.eachSeries(function (seriesModel) {
151	
152	                // mainType can be markPoint, markLine, markArea
153	                const markerOpt = seriesModel.get(
154	                    this.mainType as any, true
155	                ) as Opts;
156	
157	                let markerModel = inner(seriesModel)[componentType];
158	                if (!markerOpt || !markerOpt.data) {
159	                    inner(seriesModel)[componentType] = null;
160	                    return;
161	                }
162	                if (!markerModel) {
163	                    if (isInit) {
164	                        // Default label emphasis `position` and `show`
165	                        fillLabel(markerOpt);
166	                    }
167	                    zrUtil.each(markerOpt.data, function (item) {
168	                        // FIXME Overwrite fillLabel method ?
169	                        if (item instanceof Array) {
170	                            fillLabel(item[0]);
171	                            fillLabel(item[1]);
172	                        }
173	                        else {
174	                            fillLabel(item);
175	                        }
176	                    });
177	
178	                    markerModel = this.createMarkerModelFromSeries(
179	                        markerOpt, this, ecModel
180	                    );
181	                    // markerModel = new ImplementedMarkerModel(
182	                    //     markerOpt, this, ecModel
183	                    // );
184	
185	                    zrUtil.extend(markerModel, {
186	                        mainType: this.mainType,
187	                        // Use the same series index and name
188	                        seriesIndex: seriesModel.seriesIndex,
189	                        name: seriesModel.name,
190	                        createdBySelf: true
191	                    });
192	
193	                    markerModel.__hostSeries = seriesModel;
194	                }
195	                else {
196	                    markerModel._mergeOption(markerOpt, ecModel, true);
197	                }
198	                inner(seriesModel)[componentType] = markerModel;
199	            }, this);
200	        }
201	    }
202	
203	    formatTooltip(
204	        dataIndex: number,
205	        multipleSeries: boolean,
206	        dataType: string
207	    ) {
208	        const data = this.getData();
209	        const value = this.getRawValue(dataIndex);
210	        const itemName = data.getName(dataIndex);
211	
212	        return createTooltipMarkup('section', {
213	            header: this.name,
214	            blocks: [createTooltipMarkup('nameValue', {
215	                name: itemName,
216	                value: value,
217	                noName: !itemName,
218	                noValue: value == null
219	            })]
220	        });
221	    }
222	
223	    getData(): SeriesData<this> {
224	        return this._data as SeriesData<this>;
225	    }
226	
227	    setData(data: SeriesData) {
228	        this._data = data;
229	    }
230	
231	    getDataParams(
232	        dataIndex: number,
233	        dataType?: SeriesDataType
234	    ): CallbackDataParams {
235	        const params = DataFormatMixin.prototype.getDataParams.call(this, dataIndex, dataType);
236	        const hostSeries = this.__hostSeries;
237	        if (hostSeries) {
238	            params.seriesId = hostSeries.id;
239	            params.seriesName = hostSeries.name;
240	            params.seriesType = hostSeries.subType;
241	        }
242	        return params;
243	    }
