76	            const markerModel = MarkerModel.getMarkerModelFromSeries(
77	                seriesModel,
78	                this.type as 'markPoint' | 'markLine' | 'markArea'
79	            );
80	            if (markerModel) {
81	                const data = markerModel.getData();
82	                data.eachItemGraphicEl(function (el) {
83	                    if (el) {
84	                        isBlur ? enterBlur(el) : leaveBlur(el);
85	                    }
86	                });
87	            }
88	        });
89	    }
