198	function createData(
199	    coordSys: CoordinateSystem,
200	    seriesModel: SeriesModel,
201	    mpModel: MarkPointModel
202	) {
203	    let coordDimsInfos: SeriesDimensionDefine[];
204	    if (coordSys) {
205	        coordDimsInfos = map(coordSys && coordSys.dimensions, function (coordDim) {
206	            const info = seriesModel.getData().getDimensionInfo(
207	                seriesModel.getData().mapDimension(coordDim)
208	            ) || {};
209	            // In map series data don't have lng and lat dimension. Fallback to same with coordSys
210	            return extend(extend({}, info), {
211	                name: coordDim,
212	                // DON'T use ordinalMeta to parse and collect ordinal.
213	                ordinalMeta: null
214	            });
215	        });
216	    }
217	    else {
218	        coordDimsInfos = [{
219	            name: 'value',
220	            type: 'float'
221	        }];
222	    }
223	
224	    const mpData = new SeriesData(coordDimsInfos, mpModel);
225	    let dataOpt = map(mpModel.get('data'), curry(
226	            markerHelper.dataTransform, seriesModel
227	        ));
228	    if (coordSys) {
229	        dataOpt = filter(
230	            dataOpt, curry(markerHelper.dataFilter, coordSys)
231	        );
232	    }
233	
234	    const dimValueGetter = markerHelper.createMarkerDimValueGetter(!!coordSys, coordDimsInfos);
235	    mpData.initData(dataOpt, null, dimValueGetter);
236	
237	    return mpData;
238	}
239	
240	export default MarkPointView;
